import { VERSION, LABELS, formatCnpj } from './domain.js';
const demo=new URLSearchParams(location.search).get('demo')==='1';
const state={user:null,client:'',clients:[],route:'overview',sequence:0,import:null,worker:null,timer:null,detail:null};
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=v=>Number(v||0).toLocaleString('pt-BR'), percent=v=>`${Number(v||0).toLocaleString('pt-BR',{maximumFractionDigits:2})}%`;
const date=v=>v?new Date(v).toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'}):'Não informada';
const bytes=v=>v==null?'Não definido':`${(Number(v)/1024**3).toLocaleString('pt-BR',{maximumFractionDigits:3})} GiB`;
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',building:'M4 21V5l8-2v18 M12 8h8v13 M8 7v1 M8 11v1 M8 15v1 M16 12v1 M16 16v1 M2 21h20',upload:'M12 16V3 M7 8l5-5 5 5 M4 16v5h16v-5',file:'M14 2H5v20h14V7z M14 2v6h5 M8 12h8 M8 16h5',chart:'M3 3v18h18 M7 15l4-5 4 3 6-8',history:'M3 11a9 9 0 1 1 3 7 M3 4v7h7 M12 7v5l3 2',calculator:'M5 2h14v20H5z M8 6h8 M8 11h1 M15 11h1 M8 15h1 M15 15h1 M8 19h1 M15 19h1',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',help:'M9 9a3 3 0 0 1 6 0c0 2-3 2-3 3 4 M12 17h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',logout:'M9 3H4v18h5 M13 7l5 5-5 5 M8 12h13',menu:'M4 6h16 M4 12h16 M4 18h16',check:'M5 12l4 4L19 6',arrow:'M5 12h14 M13 6l6 6-6 6',download:'M12 3v13 M7 11l5 5 5-5 M4 17v4h16v-4',plus:'M12 4v16 M4 12h16',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',shield:'M12 2l8 4v6c0 6-8 10-8 10S4 18 4 12V6z M8 12l3 3 5-6',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M19 8a3 3 0 0 1 0 6 M22 21v-3a4 4 0 0 0-3-4',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4 M12 14v3',close:'M5 5l14 14 M19 5L5 19'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.file}"/></svg>`;
const brand=()=>`<div class="brand"><img class="brand-icon" src="/favicon.svg" alt=""><div class="brand-name">maximum<small>CNPJ INTELLIGENCE</small></div></div>`;
const statusNames={UPLOADING:'Importando',READY:'Pronto para consultar',INVALID:'Revisar importação',ESTIMATED:'Consumo estimado',STARTING:'Iniciando consulta',RUNNING:'Consultando',FETCHING:'Recebendo resultados',COMPLETED:'Concluído',FAILED:'Falha na consulta',CANCELLED:'Cancelado'};
const badge=(text,kind='')=>`<span class="badge ${kind}">${esc(text)}</span>`;
const batchBadge=s=>badge(statusNames[s]||s,s==='COMPLETED'?'green':['INVALID','FAILED'].includes(s)?'red':['UPLOADING','RUNNING','FETCHING','STARTING'].includes(s)?'amber':'');
const resultBadge=s=>badge(LABELS[s]||'Não confirmado',s==='OPTANTE'?'green':s==='NAO_CONFIRMADO'?'amber':'');
const writeAllowed=()=>['admin','operator'].includes(state.user?.role);
let toastTimer;
function toast(message){$('#toast').textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',6500);}
async function api(path,method='GET',data){
 if(demo){if(method!=='GET')throw new Error('Demonstração: nenhuma alteração ou consulta real é executada. Entre no ambiente configurado para continuar.');const {demoRequest}=await import('./demo.js');return demoRequest(path);}
 const c=new AbortController(), timeout=setTimeout(()=>c.abort(),55000);
 try{const res=await fetch(path,{method,credentials:'same-origin',headers:method==='GET'?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data),signal:c.signal});let result;try{result=await res.json();}catch{throw new Error('Resposta inesperada do servidor. Verifique a implantação.');}if(!res.ok){const e=new Error(result.message||'Não foi possível concluir a operação.');e.code=result.error;e.status=res.status;if(res.status===401 && state.user){state.user=null;login();}throw e;}return result;}catch(e){if(e.name==='AbortError')throw new Error('A requisição demorou mais que o esperado. Retome o mesmo lote; não é necessário importá-lo outra vez.');throw e;}finally{clearTimeout(timeout);}
}
function modal(title,body){const d=$('#dialog');d.innerHTML=`<div class="modal-head"><h2 id="dialog-title">${esc(title)}</h2><button data-close aria-label="Fechar">×</button></div><div class="modal-body">${body}</div>`;if(!d.open)d.showModal();$('[data-close]',d).onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d)d.close();},{once:true});}
function formData(form){return Object.fromEntries(new FormData(form));}
function header(title,subtitle,action='',eyebrow='CENTRAL DE INTELIGÊNCIA'){return `<div class="page-heading between"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function empty(title,description,action=''){return `<div class="empty">${icon('file')}<h3>${title}</h3><p>${description}</p>${action}</div>`;}
function footer(){return `<div class="footer"><span>Maximum CNPJ · Inteligência que começa com dados confiáveis.</span><span>v${VERSION} · ${demo?'Demonstração fictícia':'Fonte e referência acompanham cada consulta'}</span></div>`;}
function viewError(e){return `<div class="error-card"><h3>Não foi possível carregar esta área</h3><p>${esc(e.message)}</p><button data-nav="${state.route.split('/')[0]}">Tentar novamente</button></div>`;}
async function login(){
 clearTimeout(state.timer);document.body.classList.remove('collapsed','mobile-open');
 $('#app').innerHTML=`<div class="login"><section class="login-visual">${brand()}<div class="eyebrow muted">DADOS ORGANIZADOS. DECISÕES MELHORES.</div><h1>Um novo olhar<br>para cada<br>CNPJ.</h1><p>Da importação aos indicadores: sua carteira de empresas em uma central clara, organizada e rastreável.</p><div class="login-blocks"><div><b>01</b><small>Importe sua base</small></div><div><b>02</b><small>Consulte em lote</small></div><div><b>03</b><small>Acompanhe a evolução</small></div></div><div class="visual-bottom">Maximum · Um ecossistema em evolução. v${VERSION}</div></section><section class="login-form-wrap"><form id="login-form" class="login-form"><div><div class="eyebrow">BEM-VINDO À SUA CENTRAL</div><h2>Vamos começar?</h2><p>Acesse sua conta para acompanhar suas carteiras.</p></div><label>E-mail profissional<input type="email" name="email" placeholder="voce@empresa.com.br" required autocomplete="username"></label><label>Senha<input type="password" name="password" placeholder="Sua senha de acesso" required autocomplete="current-password" maxlength="128"></label><div class="login-error" id="login-error" role="alert"></div><button class="primary" type="submit">Entrar na central ${icon('arrow')}</button><p class="minor">Acesso restrito à equipe autorizada.<br>Solicite sua conta ao administrador do sistema.</p><button type="button" class="demo-link" id="demo-entry">Conhecer a interface em demonstração →</button><p class="minor">Dados públicos não equivalem a confirmação fiscal em tempo real.</p></form></section></div>`;
 $('#demo-entry').onclick=()=>{location.href='/?demo=1';};
 $('#login-form').onsubmit=async e=>{e.preventDefault();const btn=$('button[type=submit]',e.target);btn.disabled=true;$('#login-error').textContent='';try{await api('/api/auth/login','POST',formData(e.target));await bootstrap();}catch(error){$('#login-error').textContent=error.message;}finally{btn.disabled=false;}};
}
function shell(){
 const nav=(key,name,ic,tag='')=>`<button data-nav="${key}" title="${name}" class="${state.route.startsWith(key)?'active':''}">${icon(ic)}<span class="nav-label">${name}</span>${tag?`<span class="nav-tag">${tag}</span>`:''}</button>`;
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="workspace"><div class="workspace-symbol">M</div><div><strong>Maximum Assessoria</strong><small style="display:block;margin-top:4px;font-size:9px">Central de consultas</small></div></div><div class="nav-title">Visão estratégica</div><nav class="nav" aria-label="Navegação principal">${nav('overview','Visão geral','grid')}${nav('clients','Empresas e carteiras','building')}${nav('import','Nova importação','upload')}${nav('batches','Consultas em lote','file')}${nav('history','Histórico e evolução','chart')}</nav><div class="nav-title">Em evolução</div><nav class="nav" aria-label="Ferramentas">${nav('calculator','Calculadora tributária','calculator','FUTURO')}${nav('settings','Configurações','settings')}</nav><div class="side-bottom"><div class="support-card"><h3>Uma central feita para evoluir.</h3><p>Veja as etapas do projeto e entenda como interpretar os resultados.</p><button class="secondary" data-nav="help" style="font-size:10px">Conhecer o sistema ${icon('arrow')}</button></div><div class="side-user"><div class="avatar">${esc(state.user.name.split(' ').map(v=>v[0]).slice(0,2).join(''))}</div><div><strong>${esc(state.user.name)}</strong><small>${{admin:'Administrador',operator:'Operador',viewer:'Visualização'}[state.user.role]||'Equipe'}</small></div><button id="logout" title="Sair" aria-label="Sair da conta">${icon('logout')}</button></div></div></aside><div class="main">${demo?'<div class="demo-bar"><span>Demonstração visual · Dados fictícios. Nenhuma consulta fiscal executada.</span><button id="exit-demo">Sair da demonstração</button></div>':''}<header class="topbar"><button id="toggle-nav" class="circle-button" aria-label="Alternar navegação" aria-expanded="true">${icon('menu')}</button><span class="crumb">Workspace <span style="margin:0 8px;color:#c7c0d0">/</span> <strong style="font-weight:500;color:#62566f">Maximum CNPJ</strong></span><div class="spacer"></div><select id="global-client" aria-label="Filtrar por empresa ou carteira"><option value="">Todas as carteiras</option>${state.clients.map(c=>`<option value="${esc(c._id)}" ${state.client===c._id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><span class="divider-v"></span><button class="help-btn" data-nav="help">${icon('help')}<span>Como funciona</span></button></header><main id="content" class="content" tabindex="-1"><div class="initial"><div class="spinner"></div></div></main></div></div>`;
 $('#toggle-nav').onclick=()=>{if(innerWidth<=850)document.body.classList.toggle('mobile-open');else{document.body.classList.toggle('collapsed');localStorage.setItem('maximum-nav-collapsed',document.body.classList.contains('collapsed')?'1':'0');}$('#toggle-nav').setAttribute('aria-expanded',String(innerWidth<=850?document.body.classList.contains('mobile-open'):!document.body.classList.contains('collapsed')));};
 if(innerWidth>850 && localStorage.getItem('maximum-nav-collapsed')==='1')document.body.classList.add('collapsed');
 $('#global-client').onchange=e=>{state.client=e.target.value;navigate(state.route);};
 $('#logout').onclick=async()=>{try{if(!demo)await api('/api/auth/logout','POST',{});location.href='/';}catch(e){toast(e.message);}};
 if(demo)$('#exit-demo').onclick=()=>location.href='/';
}
function bindNavigation(){document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){e.preventDefault();document.body.classList.remove('mobile-open');navigate(nav.dataset.nav);}});window.addEventListener('hashchange',()=>{const route=location.hash.slice(1)||'overview';if(route!==state.route)renderRoute(route);});}
function navigate(route){if(route===state.route)renderRoute(route);else {location.hash=route;}}
function batchTable(items){if(!items.length)return empty('Sua primeira consulta começa aqui','Cadastre uma carteira e importe uma base para acompanhar os resultados.',writeAllowed()?'<button class="primary" data-nav="import">Nova importação</button>':'');return `<div class="table-wrap"><table><thead><tr><th>Base importada</th><th>Empresa / carteira</th><th>CNPJs únicos</th><th>Optantes</th><th>Situação</th><th></th></tr></thead><tbody>${items.map(b=>`<tr><td><div class="file"><span class="file-icon">${icon('file')}</span><div><strong>${esc(b.fileName)}</strong><small>${date(b.createdAt)}</small></div></div></td><td>${esc(b.clientName)}</td><td>${b.summary?number(b.summary.unique):'—'}</td><td>${b.resultSummary?percent(b.resultSummary.optantsPercent):'—'}</td><td>${batchBadge(b.status)}</td><td><button data-nav="batch/${esc(b._id)}">Abrir ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`;}
async function overview(){
 const data=await api('/api/dashboard'+(state.client?'?clientId='+encodeURIComponent(state.client):'')),m=data.metrics;
 const metric=(label,value,ic,sub,tag,featured=false)=>`<div class="metric ${featured?'featured':''}"><div class="row"><span class="metric-icon">${icon(ic)}</span><span class="metric-label">${label}</span></div><strong>${number(value)}</strong><div class="metric-footer"><span class="mini-pill">${tag}</span>${sub}</div></div>`;
 const latest=data.recent.find(b=>b.status==='COMPLETED');
 const degrees=m.total?m.optants/m.total*360:0,degrees2=m.total?(m.optants+m.nonOptants)/m.total*360:0;
 return header('Sua carteira, em perspectiva.','Consulte, organize e acompanhe cada empresa com mais clareza.',writeAllowed()?`<button class="primary" data-nav="import">${icon('plus')} Nova importação</button>`:'')+
 `<section class="hero"><div><h2>Menos planilhas soltas.<br>Mais inteligência para decidir.</h2><p>Uma visão única dos CNPJs da sua base, sem duplicidades nos indicadores e com histórico de cada consulta.</p><button class="primary" data-nav="import">Importar minha base ${icon('arrow')}</button></div><div class="hero-art" aria-hidden="true"><div class="hero-sheet"></div><div class="hero-check">${icon('check')}</div><div class="hero-number">CNPJ único · visão completa</div></div></section>`+
 `<section class="metrics" aria-label="Indicadores de CNPJs únicos">${metric('CNPJs acompanhados',m.total,'building','sem duplicidades','ÚNICOS')}${metric('Optantes pelo Simples',m.optants,'shield','da base consultada',percent(m.optantsPercent),true)}${metric('Não optantes',m.nonOptants,'file','da base consultada',percent(m.nonOptantsPercent))}${metric('Não confirmados',m.unknown,'search','precisam de revisão',percent(m.unknownPercent))}</section>`+
 `<div class="dashboard-grid"><section class="card"><div class="card-header between"><div><h2>Distribuição do enquadramento</h2><p>Última observação por CNPJ · conforme a fonte consultada</p></div>${badge('Simples Nacional')}</div><div class="distribution"><div class="donut" role="img" aria-label="${m.optants} optantes, ${m.nonOptants} não optantes, ${m.unknown} não confirmados" style="background:${m.total?`conic-gradient(#7a63ca 0deg ${degrees}deg,#c7bbdf ${degrees}deg ${degrees2}deg,#e7d2b1 ${degrees2}deg 360deg)`:'#eeebf3'}"><div class="donut-label"><b>${number(m.total)}</b><small>CNPJs únicos</small></div></div><div class="legend">${[['Optantes',m.optantsPercent,''],['Não optantes',m.nonOptantsPercent,'lilac'],['Não confirmados',m.unknownPercent,'sand']].map(([label,value,cls])=>`<div class="legend-line"><span class="dot ${cls}"></span><span>${label}</span><b>${percent(value)}</b></div>`).join('')}</div></div></section><section class="card"><div class="card-header"><h2>Qualidade da informação</h2><p>Mais transparência para interpretar seus indicadores</p></div><div class="quality-row"><div class="between"><span>Classificação confirmada na base</span><strong>${percent(m.coverage)}</strong></div><div class="bar"><span style="width:${m.coverage}%"></span></div></div><div class="quality-row"><div class="between"><span>Carteiras cadastradas</span><strong>${number(data.clientCount)}</strong></div></div><div class="quality-row"><div class="between"><span>MEIs entre os optantes</span><strong>${number(m.mei)}</strong></div></div><div class="note">${latest?`Último lote concluído em ${date(latest.completedAt)}.`:'Nenhuma consulta concluída ainda.'} Erros ou dados ausentes nunca são classificados como “não optante”.</div></section></div>`+
 `<section class="card"><div class="card-header between"><div><h2>Consultas recentes</h2><p>Importações e resultados organizados por carteira</p></div><button data-nav="batches">Ver todas ${icon('arrow')}</button></div>${batchTable(data.recent.slice(0,5))}</section>`;
}
async function clientsPage(){const data=await api('/api/clients');state.clients=data.items;return header('Empresas e carteiras','Defina a quem cada base pertence antes de consultar.',writeAllowed()?`<button class="primary" id="new-client">${icon('plus')} Nova carteira</button>`:'')+(!data.items.length?`<section class="card">${empty('Organize sua primeira base','Uma carteira pode representar uma empresa, um grupo ou uma lista de fornecedores. O CNPJ da responsável é opcional.','<button class="primary" id="first-client">Cadastrar carteira</button>')}</section>`:`<div class="grid3">${data.items.map(c=>`<article class="client-card"><div class="between"><div class="client-emblem">${esc(c.name.split(' ').map(w=>w[0]).slice(0,2).join(''))}</div>${badge(c.active?'Ativa':'Arquivada',c.active?'green':'')}</div><h3>${esc(c.name)}</h3><small>${c.cnpj?esc(formatCnpj(c.cnpj)):'Carteira sem CNPJ responsável'}</small><p class="hint">${esc(c.notes||'Bases e consultas vinculadas a esta carteira.')}</p><div class="between"><button data-client-open="${esc(c._id)}">Ver consultas ${icon('arrow')}</button>${writeAllowed()?`<button data-client-edit="${esc(c._id)}" title="Editar carteira">${icon('settings')}</button>`:''}</div></article>`).join('')}</div>`);}
function clientDialog(id){const client=state.clients.find(c=>c._id===id)||{};modal(id?'Editar empresa ou carteira':'Nova empresa ou carteira',`<p class="hint">Esta é a responsável pela base importada. Os CNPJs da planilha serão consultados separadamente, sem contagem duplicada.</p><form id="client-form"><label>Nome da empresa ou carteira<input name="name" value="${esc(client.name||'')}" placeholder="Ex.: Carteira de fornecedores · Empresa Alfa" maxlength="160" required></label><label>CNPJ da responsável · opcional<input name="cnpj" value="${esc(client.cnpj||'')}" placeholder="00.000.000/0001-00 ou CNPJ alfanumérico" maxlength="18"></label><label>Observações<textarea name="notes" maxlength="1000">${esc(client.notes||'')}</textarea></label>${id?`<label class="row"><input type="checkbox" name="active" ${client.active?'checked':''}> Carteira ativa para novas importações</label>`:''}<div class="actions"><button type="button" data-close-dialog>Cancelar</button><button class="primary" type="submit">Salvar carteira</button></div></form>`);$('[data-close-dialog]').onclick=()=>$('#dialog').close();$('#client-form').onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',e.target);b.disabled=true;try{const values=formData(e.target);values.active=id?$('input[name=active]',e.target).checked:true;await api('/api/clients'+(id?'/'+id:''),id?'PATCH':'POST',values);$('#dialog').close();toast('Carteira salva.');state.clients=(await api('/api/clients')).items;shell();renderRoute(state.route);}catch(error){toast(error.message);}finally{b.disabled=false;}};}
async function batchesPage(){const data=await api('/api/batches'+(state.client?'?clientId='+encodeURIComponent(state.client):''));return header('Consultas em lote','Acompanhe importações, processamento e resultados de cada base.',writeAllowed()?`<button class="primary" data-nav="import">${icon('plus')} Nova consulta</button>`:'')+`<section class="card"><div class="card-header between"><div><h2>Central de consultas</h2><p>${number(data.total)} lotes registrados · listagem paginada</p></div>${badge('Até 50.000 linhas por importação')}</div><div id="batches-table">${batchTable(data.items)}</div><div class="pagination" id="batches-pagination"><button id="batches-prev" disabled>Anterior</button><span id="batches-page">1 / ${Math.max(1,Math.ceil(data.total/30))}</span><button id="batches-next" ${data.total<=30?'disabled':''}>Próxima</button></div></section>`;}
function setupBatchPagination(){let current=1;async function load(direction){const p=current+direction;const d=await api('/api/batches?page='+p+(state.client?'&clientId='+encodeURIComponent(state.client):''));current=p;$('#batches-table').innerHTML=batchTable(d.items);$('#batches-page').textContent=`${current} / ${Math.max(1,Math.ceil(d.total/30))}`;$('#batches-prev').disabled=current===1;$('#batches-next').disabled=current*30>=d.total;}$('#batches-prev').onclick=()=>load(-1).catch(e=>toast(e.message));$('#batches-next').onclick=()=>load(1).catch(e=>toast(e.message));}
function steps(n){return `<div class="steps">${['Identificar a base','Revisar os dados','Consultar e acompanhar'].map((v,i)=>`<div class="step ${i===n?'current':''}"><b>${i+1}</b>${v}</div>`).join('')}</div>`;}
async function importPage(){if(!writeAllowed())return header('Nova importação','Importações são permitidas aos administradores e operadores.')+`<div class="warning">Seu perfil permite visualizar e exportar resultados, sem criar consultas.</div>`;return header('Uma nova base. Uma visão mais clara.','Escolha a responsável pela planilha e revise os dados antes de consultar.')+steps(0)+`<section class="card"><div class="card-header"><h2>De qual empresa ou carteira é esta base?</h2><p>Os indicadores serão vinculados à carteira escolhida.</p></div><div class="row"><select id="import-client" aria-label="Empresa ou carteira responsável"><option value="">Selecione a empresa ou carteira</option>${state.clients.filter(c=>c.active).map(c=>`<option value="${esc(c._id)}" ${state.client===c._id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><button id="import-new-client" title="Cadastrar carteira">${icon('plus')} Nova</button></div><div class="drop">${icon('upload')}<strong>Selecione sua planilha de CNPJs</strong><span class="hint">CSV ou Excel (.xlsx) · até 10 MiB · até 50.000 linhas</span><input type="file" id="import-file" accept=".csv,.xlsx" aria-label="Planilha para importar"><small>O arquivo é lido no navegador. Os dados das linhas serão armazenados no servidor somente após sua confirmação.</small></div><div class="grid2"><label>Codificação do CSV<select id="csv-encoding"><option value="utf-8">UTF-8 (recomendado)</option><option value="windows-1252">Windows-1252 / Excel antigo</option></select></label><div class="note">Mantenha o CNPJ como texto para preservar zeros à esquerda e letras. Células com fórmulas precisam ser convertidas em valores.</div></div><div id="import-progress" class="mt"></div><div id="import-mapping"></div></section>`;}
function worker(){if(!state.worker){state.worker=new Worker('/import-worker.js');state.worker.onerror=()=>toast('Falha no leitor de planilhas. Confira se npm run build foi executado.');}return state.worker;}
function workerCall(data,expected,transfer=[]){return new Promise((resolve,reject)=>{const w=worker(),timer=setTimeout(()=>{w.terminate();state.worker=null;reject(new Error('A leitura excedeu 45 segundos. Divida a planilha e tente novamente.'));},45000);const listener=({data:result})=>{if(result.type==='warning')return toast(result.message);if(result.type===expected||result.type==='error'){clearTimeout(timer);w.removeEventListener('message',listener);result.type==='error'?reject(new Error(result.message)):resolve(result);}};w.addEventListener('message',listener);w.postMessage(data,transfer);});}
async function openFile(){const file=$('#import-file').files[0];if(!file)return;state.import=null;$('#import-mapping').innerHTML='';$('#import-progress').innerHTML='<div class="row hint"><div class="spinner"></div>Lendo o arquivo no seu navegador…</div>';try{const buffer=await file.arrayBuffer();const result=await workerCall({action:'open',buffer,name:file.name,encoding:$('#csv-encoding').value},'sheets',[buffer]);state.import={fileName:file.name,sheets:result.sheets};$('#import-progress').innerHTML='';$('#import-mapping').innerHTML=`<div class="divider"></div><div class="grid2"><label>Aba da planilha<select id="import-sheet">${result.sheets.map(v=>`<option>${esc(v)}</option>`).join('')}</select></label><label>Linha de cabeçalho<select id="import-header"></select></label></div><div id="import-columns" class="mt"></div><div id="sheet-preview" class="preview-wrap"></div><div class="between wrap"><p class="hint" id="sheet-count"></p><button class="primary" id="validate-import">Revisar importação ${icon('arrow')}</button></div>`;$('#import-sheet').onchange=loadSheet;await loadSheet();$('#validate-import').onclick=validateImport;}catch(e){$('#import-progress').innerHTML='';toast(e.message);}}
function previewTable(rows){return `<table><thead><tr>${(rows[0]||[]).map((_,i)=>`<th>Coluna ${i+1}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,8).map(row=>`<tr>${row.map(v=>`<td title="${esc(v)}">${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
async function loadSheet(){try{const data=await workerCall({action:'sheet',name:$('#import-sheet').value},'preview');state.import.preview=data.rows;state.import.total=data.total;$('#import-header').innerHTML=data.rows.slice(0,10).map((_,i)=>`<option value="${i}">Linha ${i+1}</option>`).join('');$('#import-header').onchange=mapColumns;$('#sheet-preview').innerHTML=previewTable(data.rows);$('#sheet-count').textContent=`${number(data.total)} linhas não vazias na aba selecionada. Prévia de até 8 linhas.`;mapColumns();}catch(e){toast(e.message);}}
function mapColumns(){const raw=state.import.preview[Number($('#import-header').value)]||[],width=state.import.preview.reduce((n,row)=>Math.max(n,row.length),0),headers=Array.from({length:width},(_,i)=>raw[i]||`Coluna ${i+1}`);const cnpj=Math.max(0,headers.findIndex(v=>/cnpj/i.test(String(v)))),name=headers.findIndex(v=>/raz[aã]o|nome|empresa/i.test(String(v)));const options=selected=>headers.map((v,i)=>`<option value="${i}" ${i===selected?'selected':''}>${i+1}. ${esc(String(v)||'Sem título')}</option>`).join('');$('#import-columns').innerHTML=`<div class="grid2"><label>Coluna do CNPJ<select id="cnpj-column">${options(cnpj)}</select></label><label>Coluna do nome / razão social<select id="name-column"><option value="-1" ${name<0?'selected':''}>Não utilizar</option>${options(name)}</select></label></div>`;}
async function validateImport(){const b=$('#validate-import');b.disabled=true;try{const clientId=$('#import-client').value;if(!clientId)throw new Error('Selecione a empresa ou carteira responsável pela base.');const cnpjColumn=Number($('#cnpj-column').value),nameColumn=Number($('#name-column').value);const data=await workerCall({action:'validate',header:$('#import-header').value,cnpjColumn,nameColumn},'validated');state.import={...state.import,...data,clientId,cnpjColumn,nameColumn,importId:crypto.randomUUID()};showReview();}catch(e){toast(e.message);}finally{b.disabled=false;}}
function showReview(){const i=state.import,s=i.summary,c=state.clients.find(c=>c._id===i.clientId);$('#content').innerHTML=header('Confira a base antes de consultar.',esc(i.fileName)+' · '+esc(c?.name||''))+steps(1)+`<section class="card"><div class="card-header"><h2>Qualidade da importação</h2><p>Apenas CNPJs válidos e distintos serão enviados para consulta.</p></div><div class="import-totals">${[['Linhas da base',s.lines],['CNPJs únicos',s.unique],['Repetições excluídas dos KPIs',s.duplicates],['Linhas inválidas',s.invalid]].map(([label,value])=>`<div><b>${number(value)}</b><span>${label}</span></div>`).join('')}</div>${s.invalid?`<div class="warning">${number(s.invalid)} linhas inválidas serão preservadas para conferência, mas não consultadas. Elas não entram no denominador dos indicadores.</div>`:''}${i.warnings?`<div class="warning">${number(i.warnings)} CNPJs vieram de células numéricas. Confira a origem: zeros perdidos não são preenchidos automaticamente.</div>`:''}<p class="hint">CNPJs repetidos permanecem nas linhas de origem e na exportação. Cada CNPJ completo conta apenas uma vez nos indicadores. Matriz e filial com CNPJs diferentes continuam sendo estabelecimentos distintos.</p>${i.issues.length?`<div class="preview-wrap"><table><thead><tr><th>Linha de dados</th><th>CNPJ informado</th><th>Conferência</th></tr></thead><tbody>${i.issues.map(r=>`<tr><td>${r.index+1}</td><td>${esc(r.original)}</td><td>${r.reason?esc(r.reason):r.duplicate?'Repetido — não somar novamente':'Célula numérica — conferir'}</td></tr>`).join('')}</tbody></table></div><p class="hint">Prévia das primeiras 30 ocorrências. A exportação preserva todas as linhas.</p>`:''}<div id="upload-status" class="mt"></div><div class="between wrap mt"><button id="review-back">Voltar à importação</button><button class="primary" id="confirm-import" ${!s.unique?'disabled':''}>Salvar lote e continuar ${icon('arrow')}</button></div></section>`+footer();$('#review-back').onclick=()=>renderRoute('import');$('#confirm-import').onclick=uploadImport;}
async function uploadImport(){const i=state.import,button=$('#confirm-import');button.disabled=true;$('#review-back').disabled=true;try{await api('/api/batches','POST',{importId:i.importId,fileName:i.fileName,headers:i.headers,clientId:i.clientId,expectedRows:i.rows.length,cnpjColumn:i.cnpjColumn,nameColumn:i.nameColumn});let offset=i.offset||0;while(offset<i.rows.length){const rows=[];let size=100;for(let p=offset;p<i.rows.length && rows.length<250;p++){const n=new TextEncoder().encode(JSON.stringify(i.rows[p])).byteLength+1;if(rows.length&&size+n>2000000)break;rows.push(i.rows[p]);size+=n;}const result=await api(`/api/batches/${i.importId}/rows`,'POST',{offset,rows});if(result.uploaded<=offset)throw new Error('O servidor não avançou o envio. Retome este lote.');offset=result.uploaded;i.offset=offset;$('#upload-status').innerHTML=`<p class="hint">Salvando linhas: ${number(offset)} / ${number(i.rows.length)}</p><progress class="progress" value="${offset}" max="${i.rows.length}">${Math.round(offset/i.rows.length*100)}%</progress>`;}await api(`/api/batches/${i.importId}/finalize`,'POST',{});toast('Importação salva e validada pelo servidor.');navigate('batch/'+i.importId);}catch(e){toast(e.message);button.textContent='Retomar envio';}finally{button.disabled=false;$('#review-back')&&($('#review-back').disabled=false);}}
async function detailPage(id){const b=await api('/api/batches/'+encodeURIComponent(id));state.detail=b;const s=b.summary||{lines:b.uploaded,unique:0,duplicates:0,invalid:0};return header(esc(b.fileName),esc(b.clientName)+' · criado em '+date(b.createdAt),`<button data-nav="batches">Voltar aos lotes</button>`,'DETALHES DA CONSULTA')+
 `<section class="card"><div class="between wrap mb"><div><h2>Situação do lote</h2><p class="hint">${esc(b._id)}</p></div>${batchBadge(b.status)}</div><div class="import-totals">${[['Linhas importadas',s.lines],['CNPJs únicos',s.unique],['Repetições',s.duplicates],['Inválidos',s.invalid]].map(([label,value])=>`<div><b>${number(value)}</b><span>${label}</span></div>`).join('')}</div><div id="batch-action-area">${batchActions(b)}</div></section>${b.status==='COMPLETED'?`<section class="card mt"><div class="card-header between wrap"><div><h2>Resultados por CNPJ</h2><p>Fonte: ${esc(b.estimate?.source?.table||'Não informada')} · referência: ${esc(b.estimate?.source?.referenceDate||'Não informada')}</p></div><div class="row"><button id="export-csv">${icon('download')} CSV</button><button id="export-xlsx">${icon('download')} Excel</button></div></div><div class="warning">O resultado corresponde à base consultada. A data de consulta não é a data de atualização fiscal. Mudanças recentes podem ainda não aparecer.</div><div class="filter-bar"><input id="result-search" placeholder="Buscar CNPJ ou razão social" aria-label="Buscar resultados"><select id="result-status" aria-label="Filtrar enquadramento"><option value="">Todos os enquadramentos</option>${Object.entries(LABELS).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select><button id="filter-results">${icon('search')} Buscar</button></div><div id="results-table"></div><div class="pagination"><button id="result-prev" disabled>Anterior</button><span id="result-page"></span><button id="result-next">Próxima</button></div><div id="export-status" class="hint mt"></div></section>`:''}`;}
function batchActions(b){const writer=writeAllowed(),estimate=b.estimate;let out='';if(b.status==='UPLOADING')out=`<div class="warning">Envio parcial: ${number(b.uploaded)} de ${number(b.expectedRows)} linhas. A retomada do arquivo está disponível na tela de importação enquanto ela permanecer aberta. Após fechar o navegador, cancele este lote e importe o arquivo novamente.</div>`;
 if(b.status==='INVALID')out='<div class="warning">Nenhum CNPJ válido foi encontrado. Corrija a planilha e faça uma nova importação.</div>';
 if(['READY','ESTIMATED','STARTING'].includes(b.status))out=`${estimate?`<div class="settings-table"><div><span>Estimativa de dados processados</span><strong>${bytes(estimate.bytes)}</strong></div><div><span>Teto desta consulta</span><strong>${bytes(estimate.maximumBytesBilled)}</strong></div><div><span>Fonte da consulta</span><code>${esc(estimate.source?.table)}</code></div><div><span>Referência fiscal da base</span><strong>${esc(estimate.source?.referenceDate||'Não informada')}</strong></div></div>${estimate.source?.stale?'<div class="warning mt">A referência publicada excede a idade máxima configurada. Confira a atualização antes de interpretar os resultados.</div>':''}<div class="warning mt">${estimate.withinLimit?'A consulta cabe no teto configurado.':'A estimativa excede o teto. A execução está bloqueada.'} A franquia gratuita depende do uso mensal total do projeto; este painel não garante custo zero.</div>`:'<p class="hint mb">Primeiro será feita uma estimativa de consumo, sem executar o lote. A consulta só começa após sua confirmação.</p>'}<div class="row wrap">${writer&&b.status!=='STARTING'?`<button class="${estimate?'':'primary'}" id="estimate-batch">${icon('chart')} ${estimate?'Atualizar estimativa':'Estimar consulta'}</button>`:''}${writer&&estimate?.withinLimit?`<button class="primary" id="start-batch">${b.status==='STARTING'?'Retomar início da consulta':'Confirmar e consultar'} ${icon('arrow')}</button>`:''}</div>`;
 if(['RUNNING','FETCHING'].includes(b.status))out=`<div class="row"><div class="spinner"></div><p>${b.status==='RUNNING'?'O BigQuery está processando o lote.':'Recebendo e conferindo os resultados.'}</p></div><p class="hint mt">${b.status==='RUNNING'?'Nesta etapa, o provedor não informa um percentual confiável por CNPJ.':`${number(b.received)} / ${number(b.summary.unique)} resultados recebidos.`} Você pode sair desta tela e retomar pelo mesmo lote.</p>${b.status==='FETCHING'?`<progress class="progress mt" value="${b.received}" max="${b.summary.unique}"></progress>`:''}${writer?'<button class="mt" id="advance-batch">Atualizar / retomar</button>':''}`;
 if(b.status==='COMPLETED')out=`<div class="row wrap mb">${badge(`${percent(b.resultSummary.optantsPercent)} optantes`,'green')}${badge(`${percent(b.resultSummary.nonOptantsPercent)} não optantes`)}${badge(`${percent(b.resultSummary.unknownPercent)} não confirmados`,'amber')}</div><p class="hint">Lote concluído em ${date(b.completedAt)}. ${number(b.received)} CNPJs distintos reconciliados. Os indicadores globais usam a última observação de cada CNPJ, sem somar reimportações.</p>`;
 if(b.status==='FAILED')out='<div class="warning">A consulta falhou no provedor. Nenhum resultado parcial entrou nos indicadores. Confira as configurações e importe a base como um novo lote após corrigir a causa.</div>';
 if(b.status==='CANCELLED')out='<p class="hint">Este lote foi cancelado e não compõe os indicadores.</p>';
 if(writer&&!['COMPLETED','CANCELLED'].includes(b.status))out+='<div class="mt"><button class="danger" id="cancel-batch">Cancelar lote</button></div>';return out;}
function setupDetail(){const b=state.detail,id=b._id;const action=(selector,fn)=>{const button=$(selector);if(button)button.onclick=async()=>{button.disabled=true;try{await fn();await renderRoute('batch/'+id);}catch(e){toast(e.message);button.disabled=false;}};};
 action('#estimate-batch',()=>api(`/api/batches/${id}/estimate`,'POST',{}));
 const start=$('#start-batch');if(start)start.onclick=()=>{modal('Confirmar consulta em lote',`<p class="hint">${number(b.summary.unique)} CNPJs únicos serão cruzados com a base pública. Estimativa: <strong>${bytes(b.estimate.bytes)}</strong>. Teto: <strong>${bytes(b.estimate.maximumBytesBilled)}</strong>.</p><div class="warning">A cobrança depende do projeto Google Cloud e da franquia disponível. Resultados não substituem uma conferência fiscal oficial.</div><button class="primary" id="approve-query">Confirmar execução</button>`);$('#approve-query').onclick=async e=>{e.target.disabled=true;try{await api(`/api/batches/${id}/start`,'POST',{estimateId:b.estimate.id,accept:true});$('#dialog').close();renderRoute('batch/'+id);}catch(error){toast(error.message);e.target.disabled=false;}};};
 action('#advance-batch',()=>api(`/api/batches/${id}/advance`,'POST',{}));
 const cancel=$('#cancel-batch');if(cancel)cancel.onclick=()=>{modal('Cancelar este lote?',`<p class="hint">Os resultados deste lote não entrarão nos indicadores. Cancelar um job já iniciado não garante estorno de consumo no provedor.</p><button class="danger" id="approve-cancel">Confirmar cancelamento</button>`);$('#approve-cancel').onclick=async e=>{e.target.disabled=true;try{await api(`/api/batches/${id}/cancel`,'POST',{});$('#dialog').close();renderRoute('batch/'+id);}catch(error){toast(error.message);e.target.disabled=false;}};};
 if(b.status==='COMPLETED'){let current=1;const load=async(p=1)=>{const q=new URLSearchParams({page:String(p),search:$('#result-search').value,status:$('#result-status').value});const d=await api(`/api/batches/${id}/results?${q}`);if(state.route!=='batch/'+id)return;current=p;$('#results-table').innerHTML=d.items.length?`<div class="table-wrap"><table><thead><tr><th>CNPJ</th><th>Razão social</th><th>Simples Nacional</th><th>MEI</th><th>Observação</th></tr></thead><tbody>${d.items.map(r=>`<tr><td>${esc(formatCnpj(r.cnpj))}</td><td>${esc(r.name||'Não informada')}</td><td>${resultBadge(r.status)}</td><td>${r.mei===true?'Sim':r.mei===false?'Não':'Não confirmado'}</td><td>${esc(r.reason||'—')}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhum resultado neste filtro','Altere a busca ou o enquadramento.');$('#result-page').textContent=`${current} / ${Math.max(1,Math.ceil(d.total/50))} · ${number(d.total)} resultados`;$('#result-prev').disabled=current<=1;$('#result-next').disabled=current*50>=d.total;};load().catch(e=>toast(e.message));$('#filter-results').onclick=()=>load().catch(e=>toast(e.message));$('#result-search').onkeydown=e=>{if(e.key==='Enter')load().catch(error=>toast(error.message));};$('#result-prev').onclick=()=>load(current-1).catch(e=>toast(e.message));$('#result-next').onclick=()=>load(current+1).catch(e=>toast(e.message));$('#export-csv').onclick=()=>exportBatch(id,'csv');$('#export-xlsx').onclick=()=>exportBatch(id,'xlsx');}
 if(!demo&&writeAllowed()&&['RUNNING','FETCHING'].includes(b.status))state.timer=setTimeout(async()=>{if(state.route!=='batch/'+id)return;try{await api(`/api/batches/${id}/advance`,'POST',{});renderRoute('batch/'+id);}catch(e){toast(e.message);}},4000);
}
async function exportBatch(id,format){const csv=$('#export-csv'),xlsx=$('#export-xlsx');csv.disabled=xlsx.disabled=true;try{let offset=0,rows=[],headers=[];do{const data=await api(`/api/batches/${id}/export?offset=${offset}`);headers=data.headers;rows.push(...data.rows);offset=data.next;const status=$('#export-status');if(status)status.textContent=`Preparando exportação: ${number(rows.length)} linhas recebidas…`;}while(offset!==null);const data=await workerCall({action:'export',format,headers,rows},'export');const a=document.createElement('a'),url=URL.createObjectURL(data.blob);a.href=url;a.download=`${demo?'DEMONSTRACAO_':''}maximum_cnpj_${id}.${data.extension}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);if($('#export-status'))$('#export-status').textContent='Exportação concluída. As linhas originais e duplicadas foram preservadas.';}catch(e){toast(e.message);}finally{csv.disabled=xlsx.disabled=false;}}
async function historyPage(){const data=await api('/api/batches'+(state.client?'?clientId='+encodeURIComponent(state.client):'')),completed=data.items.filter(b=>b.status==='COMPLETED');return header('Cada consulta conta uma história.','Observe os registros das consultas sem confundir snapshots com um histórico fiscal oficial.')+`<div class="warning info">${state.client?'O comparativo abaixo usa lotes desta carteira.':'Selecione uma carteira no topo para comparar bases da mesma responsável.'} As listas podem ter composições diferentes; variação de percentual não comprova entrada ou saída do Simples.</div><section class="card"><div class="card-header"><h2>Snapshots recentes</h2><p>Até 30 lotes mais recentes do filtro · resultados preservados por consulta</p></div>${completed.length?`<div class="timeline">${completed.map(b=>`<div class="timeline-item"><div class="between wrap"><div><h3>${esc(b.clientName)}</h3><p>${date(b.completedAt)} · ${esc(b.fileName)}</p></div><button data-nav="batch/${esc(b._id)}" style="font-size:10px">Ver resultado ${icon('arrow')}</button></div><div class="row wrap mt">${badge(`${number(b.resultSummary.total)} únicos`)}${badge(`${percent(b.resultSummary.optantsPercent)} optantes`,'green')}${badge(`${percent(b.resultSummary.unknownPercent)} não confirmados`,'amber')}</div></div>`).join('')}</div>`:empty('O histórico será construído a cada consulta','Depois de concluir o primeiro lote, seu snapshot aparece aqui.')}</section>`;}
async function calculatorPage(){return header('O próximo capítulo da sua central.','Uma base confiável hoje, para simulações tributárias mais completas no futuro.')+`<section class="roadmap-card"><div class="lock">${icon('lock')}</div><div class="eyebrow" style="color:#9b84b3">MÓDULO EM PLANEJAMENTO</div><h2>Calculadora do Simples Nacional<br>e cenários da reforma tributária.</h2><p>A estrutura de carteiras, identidades e snapshots é o primeiro passo. O motor de cálculo ainda não está habilitado: ele precisa de regras por competência, memória de cálculo e homologação contábil antes de produzir valores.</p><div class="readiness">${icon('shield')} Nenhum cálculo fiscal é gerado nesta versão.</div></section><div class="grid3">${[['01','Dados de entrada','Receita por competência, atividade, folha, segregações e parâmetros da empresa.'],['02','Regras versionadas','Vigência, fonte normativa, versão e casos de teste documentados por regra.'],['03','Simulação auditável','Memória de cálculo, comparação de cenários e rastreabilidade dos parâmetros utilizados.']].map(([n,title,p])=>`<section class="card stack"><span class="eyebrow muted">ETAPA ${n}</span><h2>${title}</h2><p class="hint">${p}</p>${badge('Planejado')}</section>`).join('')}</div><section class="card mt"><h2>Como evoluiremos</h2><p class="hint mt">A próxima etapa técnica é homologar a fonte em um lote real com mais de 10 mil CNPJs. Depois vêm comparativos entre snapshots e o cadastro de regras tributárias. Nenhuma alíquota, exceção ou transição será presumida apenas por um CNPJ ser optante.</p></section>`;}
async function settingsPage(){const d=await api('/api/settings');return header('Configurações da central','Acompanhe a fonte, o ambiente e os acessos da equipe.')+`<div class="grid2"><section class="card"><div class="card-header between"><div><h2>Fonte das consultas</h2><p>Credenciais nunca são exibidas no navegador</p></div>${badge(d.source.approved?'Liberada pelo administrador':'Homologação pendente',d.source.approved?'green':'amber')}</div><div class="settings-table">${[['Adaptador','OpenCNPJ / BigQuery'],['Tabela',d.source.table],['Localização',d.source.location||'Não configurada'],['Referência publicada',d.source.referenceDate||'Não informada'],['Teto por consulta',bytes(d.source.maximumBytesBilled)],['Limite de importação',number(d.maxRows)+' linhas']].map(([a,b])=>`<div><span>${a}</span><code>${esc(b)}</code></div>`).join('')}</div><div class="note">A liberação da fonte não significa confirmação fiscal em tempo real. A referência publicada deve ser verificada pelo administrador.</div></section><section class="card"><div class="card-header"><h2>Conta e versão</h2><p>Seu acesso à central Maximum</p></div><div class="settings-table"><div><span>Nome</span><strong>${esc(state.user.name)}</strong></div><div><span>E-mail</span><code>${esc(state.user.email)}</code></div><div><span>Perfil</span><strong>${esc(state.user.role)}</strong></div><div><span>Versão</span><strong>${VERSION}</strong></div></div><button class="mt" id="change-password">Alterar minha senha</button><p class="hint mt">${esc(d.history)}</p></section></div>${state.user.role==='admin'?`<section class="card mt"><div class="card-header between"><div><h2>Acessos da equipe</h2><p>Administradores, operadores e visualizadores</p></div><button class="primary" id="new-user">${icon('plus')} Novo acesso</button></div><div id="users-table"></div></section><section class="card mt"><div class="card-header"><h2>Trilha de auditoria</h2><p>100 operações mais recentes no workspace</p></div><div id="audit-table"></div></section>`:''}`;}
function passwordDialog(required=false){modal(required?'Redefina sua senha para continuar':'Alterar minha senha',`<form id="password-form"><p class="hint">Use entre 12 e 128 caracteres. Todas as suas sessões serão encerradas após a alteração.</p><label>Senha atual<input name="current" type="password" required autocomplete="current-password" maxlength="128"></label><label>Nova senha<input name="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"></label><label>Confirme a nova senha<input name="confirm" type="password" required minlength="12" maxlength="128" autocomplete="new-password"></label><button class="primary" type="submit">Salvar nova senha</button></form>`);$('#password-form').onsubmit=async e=>{e.preventDefault();const data=formData(e.target),btn=$('button',e.target);if(data.password!==data.confirm)return toast('A confirmação da senha não corresponde.');btn.disabled=true;try{await api('/api/auth/password','POST',data);$('#dialog').close();state.user=null;login();toast('Senha alterada. Entre novamente.');}catch(error){toast(error.message);}finally{btn.disabled=false;}};}
function userDialog(){modal('Novo acesso da equipe',`<form id="user-form"><label>Nome<input name="name" required maxlength="160" autocomplete="name"></label><label>E-mail<input name="email" required type="email" autocomplete="email"></label><label>Perfil<select name="role"><option value="viewer">Visualizador — consultar e exportar resultados</option><option value="operator">Operador — importar e executar consultas</option><option value="admin">Administrador — gerenciar acessos</option></select></label><label>Senha inicial<input name="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"></label><p class="hint">O usuário será obrigado a redefinir a senha no primeiro acesso. Transmita a senha inicial por um canal seguro.</p><button class="primary" type="submit">Criar acesso</button></form>`);$('#user-form').onsubmit=async e=>{e.preventDefault();const btn=$('button',e.target);btn.disabled=true;try{await api('/api/users','POST',formData(e.target));$('#dialog').close();toast('Acesso criado com redefinição obrigatória.');renderRoute('settings');}catch(error){toast(error.message);}finally{btn.disabled=false;}};}
async function setupSettings(){ $('#change-password').onclick=()=>passwordDialog();if(state.user.role!=='admin')return;$('#new-user').onclick=userDialog;try{const [users,audit]=await Promise.all([api('/api/users'),api('/api/audit')]);if(state.route!=='settings')return;$('#users-table').innerHTML=users.items.length?`<div class="table-wrap"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Situação</th></tr></thead><tbody>${users.items.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(u.role)}</td><td>${badge(u.active?'Ativo':'Inativo',u.active?'green':'')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="hint">Nenhum acesso listado neste ambiente.</p>';$('#audit-table').innerHTML=audit.items.length?`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Ação</th><th>Registro</th><th>Responsável (ID)</th></tr></thead><tbody>${audit.items.map(a=>`<tr><td>${date(a.createdAt)}</td><td>${esc(a.action)}</td><td>${esc(a.target)}</td><td>${esc(a.actor)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="hint">Nenhuma operação registrada.</p>';}catch(e){toast(e.message);}}
async function helpPage(){return header('Entenda sua central.','Um guia para importar, consultar e interpretar os resultados com segurança.')+`<article class="card help-article"><h2>1. A quem pertence esta base?</h2><p>Cadastre uma empresa ou carteira e escolha-a na importação. A responsável pela lista não precisa ser um dos CNPJs que serão consultados. Você pode ter carteiras por cliente, grupo ou segmento.</p><h2>2. O que acontece com CNPJs repetidos?</h2><p>As linhas originais são preservadas para auditoria e exportação. Para consultar e calcular percentuais, o sistema considera cada CNPJ válido completo apenas uma vez. Nos indicadores gerais, utiliza a última observação de cada CNPJ entre os lotes concluídos.</p><h2>3. Como interpretar os percentuais?</h2><p>Optantes, não optantes e não confirmados usam o total de CNPJs válidos únicos como denominador. Linhas inválidas ficam fora. MEI é um subconjunto dos optantes, não uma quarta categoria a somar. A cobertura informa a parcela com resposta explícita positiva ou negativa.</p><h2>4. Quando um resultado é “não confirmado”?</h2><p>Quando o CNPJ não está na fonte, o indicador é desconhecido ou há conflito entre os dados. Uma falha no provedor impede a conclusão do lote: ela nunca vira “não optante”.</p><h2>5. A consulta é gratuita e em tempo real?</h2><p>A integração usa uma base pública no BigQuery e depende das condições e limites do projeto Google Cloud. A estimativa e o teto por consulta ajudam a controlar consumo, mas não garantem gratuidade mensal. A consulta reflete a atualização da base, não uma verificação instantânea no portal oficial.</p><h2>6. Posso fechar a tela durante a consulta?</h2><p>Após o job iniciar no BigQuery, sim. O identificador fica salvo e você pode retomar pelo mesmo lote. O recebimento das páginas continua quando um operador abre o lote. O envio inicial de um arquivo só pode ser retomado na mesma sessão da tela de importação.</p><h2>7. Como acompanhar a evolução?</h2><p>O histórico preserva snapshots das consultas feitas neste sistema. Não é um histórico oficial completo do Simples Nacional. Compare bases equivalentes e confira a referência temporal antes de interpretar variações.</p><h2>8. O que vem depois?</h2><p>Homologação em lote real, comparações por CNPJ entre snapshots, notificações e regras tributárias versionadas. A calculadora permanece bloqueada até ter motor de cálculo e homologação fiscal próprios.</p><h2>Documentação e segurança</h2><p>O README, o CHANGELOG e o plano de evolução acompanham o código no repositório. Nenhuma senha padrão é criada; a conta administrativa é provisionada no servidor.</p><div class="note">Versão ${VERSION}. A demonstração usa dados fictícios e não consulta nenhuma empresa real.</div></article>`;}
async function renderRoute(route){
 if(!state.user)return;state.route=route;clearTimeout(state.timer);const seq=++state.sequence;
 $$('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.nav===(route.startsWith('batch/')?'batches':route)));
 const c=$('#content');if(!c)return;c.innerHTML='<div class="initial"><div class="row" style="justify-content:center"><div class="spinner"></div>Carregando sua central…</div></div>';
 try{let html;if(route==='overview')html=await overview();else if(route==='clients')html=await clientsPage();else if(route==='import')html=await importPage();else if(route==='batches')html=await batchesPage();else if(route.startsWith('batch/'))html=await detailPage(route.slice(6));else if(route==='history')html=await historyPage();else if(route==='calculator')html=await calculatorPage();else if(route==='settings')html=await settingsPage();else html=await helpPage();if(seq!==state.sequence)return;c.innerHTML=html+footer();
 if(route==='clients'){$('#new-client')&&($('#new-client').onclick=()=>clientDialog());$('#first-client')&&($('#first-client').onclick=()=>clientDialog());$$('[data-client-edit]').forEach(b=>b.onclick=()=>clientDialog(b.dataset.clientEdit));$$('[data-client-open]').forEach(b=>b.onclick=()=>{state.client=b.dataset.clientOpen;$('#global-client').value=state.client;navigate('batches');});}
 if(route==='import'&&writeAllowed()){$('#import-file').onchange=openFile;$('#import-new-client').onclick=()=>clientDialog();$('#csv-encoding').onchange=()=>{if($('#import-file').files.length)openFile();};}
 if(route==='batches')setupBatchPagination();if(route.startsWith('batch/'))setupDetail();if(route==='settings')setupSettings();
 }catch(e){if(seq===state.sequence && state.user)c.innerHTML=viewError(e)+footer();}
}
async function bootstrap(){try{const session=await api('/api/auth/me');state.user=session.user;if(state.user.mustChangePassword){$('#app').innerHTML='<div class="initial">Redefina sua senha inicial para acessar a central.</div>';passwordDialog(true);return;}state.clients=(await api('/api/clients')).items;state.route=location.hash.slice(1)||'overview';shell();await renderRoute(state.route);}catch(e){state.user=null;login();if(e.status!==401)toast(e.message);}}
bindNavigation();bootstrap();
